import{_ as o,o as e,c as r,a5 as d}from"./chunks/framework.Cooo9kuv.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{"标题":"批量重命名文件夹下文件名-封面识别-逻辑验证添加文件名后缀","日期":"2026-04-18T00:00:00.000Z","修改日期":"2026-04-18T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["定制类程序"],"标签":["Python重命名工具","图片重命名工具","封面识别","批量重命名","文件夹批量处理","文件重命名软件","智能重命名","漫画重命名"]},"headers":[],"relativePath":"md/定制类程序/批量重命名文件夹下文件名-封面识别-逻辑验证添加文件名后缀.md","filePath":"md/定制类程序/批量重命名文件夹下文件名-封面识别-逻辑验证添加文件名后缀.md"}'),a={name:"md/定制类程序/批量重命名文件夹下文件名-封面识别-逻辑验证添加文件名后缀.md"};function n(s,t,l,c,i,g){return e(),r("div",null,[...t[0]||(t[0]=[d('<p>用于批量重命名文件夹下的图片文件。通过模板匹配识别第一张图片是否为封面，并自动应用不同的重命名规则，非常适合政务类文档整理区分封面的图像序列。</p><h3 id="功能特点" tabindex="-1">功能特点 <a class="header-anchor" href="#功能特点" aria-label="Permalink to &quot;功能特点&quot;">​</a></h3><ul><li><strong>智能封面识别</strong>：通过对比第一张图片与参考模板的颜色直方图相似度，判断是否为封面。</li><li><strong>两种重命名模式</strong>： <ul><li><strong>封面模式</strong>：当第一张图被识别为封面时，前3张图片添加 <code>-1</code>、<code>-2</code>、<code>-3</code> 后缀，其余添加 <code>-1</code>。</li><li><strong>普通模式</strong>：所有文件统一添加 <code>-1</code> 后缀。</li></ul></li><li><strong>灵活的文件命名</strong>：新文件名格式为 <code>[文件夹名]-[原文件名最后3位数字][后缀].扩展名</code>。</li><li><strong>批量处理子文件夹</strong>：支持一次性处理所选路径下的所有子文件夹（批量模式）。</li><li><strong>自然排序</strong>：文件名按数字顺序自然排序（例如 <code>2.jpg</code> 在 <code>10.jpg</code> 之前）。</li><li><strong>配置记忆</strong>：自动保存上次选择的文件夹路径和参考模板路径。</li><li><strong>实时日志显示</strong>：处理过程及结果在界面中实时滚动显示。</li></ul><h3 id="程序截图" tabindex="-1">程序截图 <a class="header-anchor" href="#程序截图" aria-label="Permalink to &quot;程序截图&quot;">​</a></h3><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/image-6.png" alt=""></p><h3 id="详细使用说明" tabindex="-1">详细使用说明 <a class="header-anchor" href="#详细使用说明" aria-label="Permalink to &quot;详细使用说明&quot;">​</a></h3><ul><li>点击 <strong>浏览</strong> 选择包含图片文件夹的<strong>父目录</strong>。</li><li>(可选) 点击 <strong>选择参考模板</strong>，选取一张代表封面的典型图片。</li><li>调整 <strong>相似度阈值</strong> 滑块（默认 30%）。若第一张图与模板的相似度超过此值，则判定为封面。</li><li>勾选 <strong>“对路径下每个子文件夹进行处理”</strong> 以启用批量模式。</li><li>点击 <strong>开始批量重命名</strong>。</li><li>在下方日志区域观察处理进度和结果。</li></ul><h3 id="重命名规则说明" tabindex="-1">重命名规则说明 <a class="header-anchor" href="#重命名规则说明" aria-label="Permalink to &quot;重命名规则说明&quot;">​</a></h3><table tabindex="0"><thead><tr><th>情况</th><th>封面判定结果</th><th>前3张文件后缀</th><th>其余文件后缀</th><th>示例文件名（原文件夹名 <code>Chapter1</code>，原文件 <code>page_005.jpg</code>）</th></tr></thead><tbody><tr><td>相似度 <strong>&gt;</strong> 阈值</td><td>是封面</td><td><code>-1</code>, <code>-2</code>, <code>-3</code></td><td><code>-1</code></td><td><code>Chapter1-005-1.jpg</code> (第1张)</td></tr><tr><td>相似度 <strong>≤</strong> 阈值</td><td>非封面</td><td><code>-1</code> (全部)</td><td><code>-1</code></td><td><code>Chapter1-005-1.jpg</code> (所有文件)</td></tr><tr><td>相似度 <strong>≤</strong> 阈值</td><td>非封面</td><td><code>-1</code> (全部)</td><td><code>-1</code></td><td><code>Chapter1-005-1.jpg</code> (所有文件)</td></tr></tbody></table><ul><li><strong>数字提取规则</strong>：程序会提取原文件名（不含扩展名）中的<strong>最后一组数字的最后3位</strong>。例如 <code>img_12345.jpg</code> → <code>345</code>；<code>abc.jpg</code> → 保留原 <code>abc</code>。</li></ul><h3 id="关于配置文件" tabindex="-1">关于配置文件 <a class="header-anchor" href="#关于配置文件" aria-label="Permalink to &quot;关于配置文件&quot;">​</a></h3><p>程序会在您的用户目录下（不需要去管这个文件在哪，想找到可以在C盘搜索）自动创建配置文件 <code>.renamer_config.json</code>，用于记忆：</p><ul><li>上次选择的文件夹路径</li><li>上次选择的参考模板路径</li></ul><h3 id="程序使用环境及相关说明" tabindex="-1">程序使用环境及相关说明 <a class="header-anchor" href="#程序使用环境及相关说明" aria-label="Permalink to &quot;程序使用环境及相关说明&quot;">​</a></h3><p><strong>1、适用的系统环境说明</strong>：</p><p>win7及以上64位win操作系统 ，  **注意事项：**win32位系统以及mac系统需要额外定制开发</p><p><strong>2、关于使用限制</strong>：</p><p>①无需注册、登录等限制，直接使用，  ②没有电脑台数限制，  ③无使用时间限制、不联网本地使用、确保数据安全</p><p><strong>3、程序如何安装</strong>：不需要安装，按照说明使用即可。</p><p><strong>特别注意</strong>：请先测试，注意备份原文件，之后再批量使用，避免不可逆损失。</p><h3 id="程序使用说明" tabindex="-1">程序使用说明 <a class="header-anchor" href="#程序使用说明" aria-label="Permalink to &quot;程序使用说明&quot;">​</a></h3><p>拿到压缩包后<strong>解压后直接使用即可，程序可以放在任意位置</strong></p><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/2692.html" target="_blank" rel="noreferrer">https://www.softbangong.com/2692.html</a></p>',24)])])}const p=o(a,[["render",n]]);export{_ as __pageData,p as default};
